import{_ as l,a0 as d,w as n,s as r,ao as p,I as i,x as s,a1 as t,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171007 How to use GNU Stow to manage programs installed from source and dotfiles","title":"如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件","tag":"201803","desc":""},"relativePath":"201803/20171007 How to use GNU Stow to manage programs installed from source and dotfiles.md","filePath":"[post].md"}'),c={name:"201803/20171007 How to use GNU Stow to manage programs installed from source and dotfiles.md"};function h(g,e,u,b,k,f){const a=d("Link");return n(),r("div",null,[e[13]||(e[13]=p(`<h1 id="如何使用-gnu-stow-來管理從源代碼安裝的程序和點文件" tabindex="-1">如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件 <a class="header-anchor" href="#如何使用-gnu-stow-來管理從源代碼安裝的程序和點文件" aria-label="Permalink to “如何使用 GNU Stow 來管理從源代碼安裝的程序和點文件”">​</a></h1><h3 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to “目的”">​</a></h3><p>使用 GNU Stow 輕鬆管理從源代碼安裝的程序和點文件（LCTT 譯註：<ruby>點文件<rt>dotfile</rt></ruby>，即以 <code>.</code> 開頭的文件，在 *nix 下默認為隱藏文件，常用於存儲程序的配置信息。）</p><h3 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h3><ul><li>root 權限</li></ul><h3 id="難度" tabindex="-1">難度 <a class="header-anchor" href="#難度" aria-label="Permalink to “難度”">​</a></h3><p>簡單</p><h3 id="約定" tabindex="-1">約定 <a class="header-anchor" href="#約定" aria-label="Permalink to “約定”">​</a></h3><ul><li><code>#</code> - 給定的命令要求直接以 root 用户身份或使用 <code>sudo</code> 命令以 root 權限執行</li><li><code>$</code> - 給定的命令將作為普通的非特權用户來執行</li></ul><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>有時候我們必須從源代碼安裝程序，因為它們也許不能通過標準渠道獲得，或者我們可能需要特定版本的軟件。 GNU Stow 是一個非常不錯的<ruby>符號鏈接工廠<rt>symlinks factory</rt></ruby>程序，它可以幫助我們保持文件的整潔，易於維護。</p><h3 id="獲得-stow" tabindex="-1">獲得 stow <a class="header-anchor" href="#獲得-stow" aria-label="Permalink to “獲得 stow”">​</a></h3><p>你的 Linux 發行版本很可能包含 <code>stow</code>，例如在 Fedora，你安裝它只需要：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install stow</span></span></code></pre></div><p>在 Ubuntu/Debian 中，安裝 <code>stow</code> 需要執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install stow</span></span></code></pre></div><p>在某些 Linux 發行版中，<code>stow</code> 在標準庫中是不可用的，但是可以通過一些額外的軟件源（例如 RHEL 和 CentOS7 中的EPEL ）輕鬆獲得，或者，作為最後的手段，你可以從源代碼編譯它。只需要很少的依賴關係。</p><h3 id="從源代碼編譯" tabindex="-1">從源代碼編譯 <a class="header-anchor" href="#從源代碼編譯" aria-label="Permalink to “從源代碼編譯”">​</a></h3><p>最新的可用 stow 版本是 <code>2.2.2</code>。源碼包可以在這裏下載：<code>https://ftp.gnu.org/gnu/stow/</code>。</p><p>一旦你下載了源碼包，你就必須解壓它。切換到你下載軟件包的目錄，然後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvpzf stow-2.2.2.tar.gz</span></span></code></pre></div><p>解壓源文件後，切換到 <code>stow-2.2.2</code> 目錄中，然後編譯該程序，只需運行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span></code></pre></div><p>最後，安裝軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># make install</span></span></code></pre></div><p>默認情況下，軟件包將安裝在 <code>/usr/local/</code> 目錄中，但是我們可以改變它，通過配置腳本的 <code>--prefix</code> 選項指定目錄，或者在運行 <code>make install</code> 時添加 <code>prefix=&quot;/your/dir&quot;</code>。</p><p>此時，如果所有工作都按預期工作，我們應該已經在系統上安裝了 <code>stow</code>。</p><h3 id="stow-是如何工作的" tabindex="-1">stow 是如何工作的？ <a class="header-anchor" href="#stow-是如何工作的" aria-label="Permalink to “stow 是如何工作的？”">​</a></h3><p><code>stow</code> 背後主要的概念在程序手冊中有很好的解釋：</p><blockquote><p>Stow 使用的方法是將每個軟件包安裝到自己的目錄樹中，然後使用符號鏈接使它看起來像文件一樣安裝在公共的目錄樹中</p></blockquote><p>為了更好地理解這個軟件的運作，我們來分析一下它的關鍵概念：</p><h4 id="stow-文件目錄" tabindex="-1">stow 文件目錄 <a class="header-anchor" href="#stow-文件目錄" aria-label="Permalink to “stow 文件目錄”">​</a></h4><p>stow 目錄是包含所有 stow 軟件包的根目錄，每個包都有自己的子目錄。典型的 stow 目錄是 <code>/usr/local/stow</code>：在其中，每個子目錄代表一個軟件包。</p><h4 id="stow-軟件包" tabindex="-1">stow 軟件包 <a class="header-anchor" href="#stow-軟件包" aria-label="Permalink to “stow 軟件包”">​</a></h4><p>如上所述，stow 目錄包含多個“軟件包”，每個軟件包都位於自己單獨的子目錄中，通常以程序本身命名。包就是與特定軟件相關的文件和目錄列表，作為一個實體進行管理。</p><h4 id="stow-目標目錄" tabindex="-1">stow 目標目錄 <a class="header-anchor" href="#stow-目標目錄" aria-label="Permalink to “stow 目標目錄”">​</a></h4><p>stow 目標目錄解釋起來是一個非常簡單的概念。它是包文件應該安裝到的目錄。默認情況下，stow 目標目錄被視作是調用 stow 的目錄。這種行為可以通過使用 <code>-t</code> 選項（ <code>--target</code> 的簡寫）輕鬆改變，這使我們可以指定一個替代目錄。</p><h3 id="一個實際的例子" tabindex="-1">一個實際的例子 <a class="header-anchor" href="#一個實際的例子" aria-label="Permalink to “一個實際的例子”">​</a></h3><p>我相信一個好的例子勝過 1000 句話，所以讓我來展示 <code>stow</code> 如何工作。假設我們想編譯並安裝 <code>libx264</code>，首先我們克隆包含其源代碼的倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone git://git.videolan.org/x264.git</span></span></code></pre></div><p>運行該命令幾秒鐘後，將創建 <code>x264</code> 目錄，它將包含準備編譯的源代碼。我們切換到 <code>x264</code> 目錄中並運行 <code>configure</code> 腳本，將 <code>--prefix</code> 指定為 <code>/usr/local/stow/libx264</code> 目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd x264 &amp;&amp; ./configure --prefix=/usr/local/stow/libx264</span></span></code></pre></div><p>然後我們構建該程序並安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make</span></span>
<span class="line"><span># make install</span></span></code></pre></div><p><code>x264</code> 目錄應該創建在 <code>stow</code> 目錄內：它包含了所有通常直接安裝在系統中的東西。 現在，我們所要做的就是調用 <code>stow</code>。 我們必須從 <code>stow</code> 目錄內運行這個命令，通過使用 <code>-d</code> 選項來手動指定 <code>stow</code> 目錄的路徑（默認為當前目錄），或者通過如前所述用 <code>-t</code> 指定目標。我們還應該提供要作為參數存儲的軟件包的名稱。 在這裏，我們從 <code>stow</code> 目錄運行程序，所以我們需要輸入的內容是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stow libx264</span></span></code></pre></div><p>libx264 軟件包中包含的所有文件和目錄現在已經在調用 stow 的父目錄 (/usr/local) 中進行了符號鏈接，因此，例如在 <code>/usr/local/ stow/x264/bin</code> 中包含的 libx264 二進制文件現在符號鏈接在 <code>/usr/local/bin</code> 之中，<code>/usr/local/stow/x264/etc</code> 中的文件現在符號鏈接在 <code>/usr/local/etc</code> 之中等等。通過這種方式，系統將顯示文件已正常安裝，並且我們可以容易地跟蹤我們編譯和安裝的每個程序。要反轉該操作，我們只需使用 <code>-D</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stow -d libx264</span></span></code></pre></div><p>完成了！符號鏈接不再存在：我們只是“卸載”了一個 stow 包，使我們的系統保持在一個乾淨且一致的狀態。 在這一點上，我們應該清楚為什麼 stow 還可以用於管理點文件。 通常的做法是在 git 倉庫中包含用户特定的所有配置文件，以便輕鬆管理它們並使它們在任何地方都可用，然後使用 stow 將它們放在適當位置，如放在用户主目錄中。</p><p>stow 還會阻止你錯誤地覆蓋文件：如果目標文件已經存在，並且沒有指向 stow 目錄中的包時，它將拒絕創建符號鏈接。 這種情況在 stow 術語中稱為衝突。</p><p>就是這樣！有關選項的完整列表，請參閲 stow 幫助頁，並且不要忘記在評論中告訴我們你對此的看法。</p><hr>`,52)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),t(a,{href:"https://linuxconfig.org/how-to-use-gnu-stow-to-manage-programs-installed-from-source-and-dotfiles"},{default:o(()=>[...e[0]||(e[0]=[s("https://linuxconfig.org/how-to-use-gnu-stow-to-manage-programs-installed-from-source-and-dotfiles",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=s("作者：",-1)),t(a,{href:"https://linuxconfig.org"},{default:o(()=>[...e[2]||(e[2]=[s("Egidio Docile",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),t(a,{href:"https://github.com/MjSeven"},{default:o(()=>[...e[3]||(e[3]=[s("MjSeven",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const y=l(c,[["render",h]]);export{x as __pageData,y as default};
